import 'package:kaisel/kaisel.dart';

import 'receive_request/cubit.dart' show ReceiveRequestStatus;
import 'routes.dart';

/// The only place in the app where URL strings exist.
///
/// The four invite paths (`/c`, `/p`, `/o`, `/i`) are external contracts —
/// they are generated by `profileUrl` and the invite builders in `utils.dart`
/// and printed into QR codes, so their shape must not change. The payload
/// rides in the URI fragment, which reaches [decode] untouched.
class AppCodec extends KaiselConfigCodec<AppRoute> {
  const AppCodec();

  /// A config that lands inside the shell, on [branch], with [stack] as that
  /// branch's history.
  static KaiselConfig<AppRoute> _shell(
    AppBranch branch,
    List<KaiselRoute> stack,
  ) => KaiselConfig(
    mainStack: const [ShellHost()],
    nestedState: KaiselShellConfig(
      activeBranch: branch.index,
      activeBranchStack: stack,
    ),
  );

  @override
  KaiselConfig<AppRoute>? decode(Uri uri) {
    // Drop empty segments so the `/c/` and `/c` variants land on the same
    // arm — the cubit's URL parsing has carried a TODO about exactly this.
    final segments = uri.pathSegments
        .where((s) => s.isNotEmpty)
        .map((s) => s.toLowerCase())
        .toList();

    // Deep links land on a breadcrumb stack, not a bare screen, so back from
    // a cold link goes somewhere coherent instead of exiting the app.
    ReceiveRequest invite(ReceiveRequestStatus status) =>
        ReceiveRequest(status, fragment: uri.fragment);

    return switch (segments) {
      ['c'] => _shell(AppBranch.contacts, [
        const ContactList(),
        invite(ReceiveRequestStatus.handleDirectSharing),
      ]),
      ['p'] => _shell(AppBranch.contacts, [
        const ContactList(),
        invite(ReceiveRequestStatus.handleProfileLink),
      ]),
      ['o'] => _shell(AppBranch.contacts, [
        const ContactList(),
        invite(ReceiveRequestStatus.handleSharingOffer),
      ]),
      ['i'] => _shell(AppBranch.contacts, [
        const ContactList(),
        invite(ReceiveRequestStatus.handleCommunityInvite),
      ]),
      ['mapatlocation', final lat, final lng] => _shell(AppBranch.map, [
        MapView(
          latitude: double.tryParse(lat),
          longitude: double.tryParse(lng),
        ),
      ]),
      [] => _shell(AppBranch.dashboard, const [DashboardView()]),
      ['profile'] => _shell(AppBranch.profile, const [ProfileHome()]),
      ['circles'] => _shell(AppBranch.circles, const [CirclesList()]),
      ['contacts'] => _shell(AppBranch.contacts, const [ContactList()]),
      ['map'] => _shell(AppBranch.map, const [MapView()]),
      ['updates'] => _shell(AppBranch.dashboard, const [
        DashboardView(),
        Updates(),
      ]),
      ['settings'] => _shell(AppBranch.dashboard, const [
        DashboardView(),
        Settings(),
      ]),
      ['welcome'] => KaiselConfig(mainStack: const [Welcome()]),
      ['introductions'] => KaiselConfig(
        mainStack: const [ShellHost(), Introductions()],
      ),
      _ => KaiselConfig(mainStack: [NotFound(uri)]),
    };
  }

  @override
  Uri encode(KaiselConfig<AppRoute> config) {
    final top = config.mainStack.last;
    return switch (top) {
      Welcome() => Uri(path: '/welcome'),
      RestoreBackup() => Uri(path: '/restoreBackup'),
      Introductions() => Uri(path: '/introductions'),
      IntroduceContact() => Uri(path: '/introductions'),
      Terms() => Uri(path: '/terms'),
      Privacy() => Uri(path: '/privacy'),
      NotFound(:final uri) => uri,
      ShellHost() => _encodeShell(config.nestedState),
    };
  }

  Uri _encodeShell(KaiselNestedConfig? nested) {
    if (nested is! KaiselShellConfig) return Uri(path: '/');
    final top = nested.activeBranchStack.last;
    return switch (top) {
      // Dashboard
      DashboardView() => Uri(path: '/'),
      Updates() => Uri(path: '/updates'),
      Settings() => Uri(path: '/settings'),
      ManageBackup() => Uri(path: '/settings'),
      Licenses() => Uri(path: '/settings'),
      DebugInfo() => Uri(path: '/settings'),
      Developer() => Uri(path: '/settings'),
      // Profile
      ProfileHome() => Uri(path: '/profile'),
      // Circles
      CirclesList() => Uri(path: '/circles'),
      CircleDetails() => Uri(path: '/circles'),
      // Contacts
      ContactList() => Uri(path: '/contacts'),
      // Carries a whole CoagContact, so it has no URL form of its own.
      ContactView() => Uri(path: '/contacts'),
      CreateNewContact() => Uri(path: '/contacts'),
      LinkToSystemContact() => Uri(path: '/contacts'),
      ReceiveRequest(:final status, :final fragment) => Uri(
        path: _invitePath(status),
        fragment: (fragment?.isEmpty ?? true) ? null : fragment,
      ),
      // Map
      MapView(:final latitude, :final longitude) =>
        (latitude == null || longitude == null)
            ? Uri(path: '/map')
            : Uri(path: '/mapAtLocation/$latitude/$longitude'),
      ImportIcs() => Uri(path: '/map'),
      LocationList() => Uri(path: '/map'),
      CalendarEvents() => Uri(path: '/map'),
      ScheduleLocation() => Uri(path: '/map'),
      ShareLocation() => Uri(path: '/map'),
      // The branch stacks are type-erased to KaiselRoute, so the switch
      // cannot be exhaustive over all five families at once.
      _ => Uri(path: '/'),
    };
  }

  static String _invitePath(ReceiveRequestStatus status) => switch (status) {
    ReceiveRequestStatus.handleDirectSharing => '/c',
    ReceiveRequestStatus.handleProfileLink => '/p',
    ReceiveRequestStatus.handleSharingOffer => '/o',
    ReceiveRequestStatus.handleCommunityInvite => '/i',
    _ => '/contacts',
  };
}
